 // Package gg implements simple "extensions" to Go language. Based on https://github.com/icza/gog
 package gg

+// P returns a pointer to v, including when v is the zero value.
+func P[T any](v T) *T { return &v }
+
+// V returns the value pointed to by p, or the zero value when p is nil.
+func V[T any](p *T) T {
+	if p == nil {
+		var zero T
+		return zero
+	}
+	return *p
+}
